package io.screentrace.adapter.struts;
import org.junit.jupiter.api.Test;import org.junit.jupiter.api.io.TempDir;import java.nio.file.*;import io.screentrace.scanner.ProjectScanner;import io.screentrace.core.ApplicationGraph.*;import static org.junit.jupiter.api.Assertions.*;
class Batch5SpringProxyTest {
 @TempDir Path root;void write(String name,String text)throws Exception{Path f=root.resolve(name);Files.createDirectories(f.getParent());Files.writeString(f,text);}
 @Test void actionPathBindsTheUniqueSpringBeanAndRetainsGlobalForward()throws Exception{
 write("WebRoot/WEB-INF/web.xml","<web-app><servlet><servlet-name>a</servlet-name><servlet-class>org.apache.struts.action.ActionServlet</servlet-class></servlet><servlet-mapping><servlet-name>a</servlet-name><url-pattern>*.do</url-pattern></servlet-mapping></web-app>");
 write("WebRoot/WEB-INF/struts-config.xml","<struts-config><global-forwards><forward name='login' path='/index.jsp'/></global-forwards><action-mappings><action path='/save' type='org.springframework.web.struts.DelegatingActionProxy'><forward name='done' path='/done.jsp'/></action></action-mappings></struts-config>");write("src/applicationContext-actions.xml","<beans><bean name='/save' class='Save'/></beans>");write("src/Save.java","class Save extends Action{public ActionForward execute(ActionMapping m,ActionForm f,HttpServletRequest r,HttpServletResponse s){if(flag)return m.findForward(\"login\");return m.findForward(\"done\");}}");write("WebRoot/index.jsp","Login");write("WebRoot/done.jsp","Done");
 var graph=new StrutsProjectAnalyzer().analyze(new ProjectScanner().scan(root));var h=graph.nodes().stream().filter(n->n.type()==NodeType.HANDLER&&"/save".equals(n.attributes().get("path"))).findFirst().orElseThrow();assertEquals("Save",h.attributes().get("actionType"));assertTrue(h.evidence().stream().anyMatch(e->e.parser().equals("SpringActionBinding")));assertEquals(2,graph.relationships().stream().filter(e->e.from().equals(h.id())&&e.type()==EdgeType.FORWARDS_TO).map(Relationship::to).distinct().count());
 }
 @Test void commandForwardKeepsInheritedAuthenticationButExcludesOtherDispatchViews()throws Exception{
 write("WebRoot/WEB-INF/web.xml","<web-app><servlet><servlet-name>a</servlet-name><servlet-class>org.apache.struts.action.ActionServlet</servlet-class></servlet><servlet-mapping><servlet-name>a</servlet-name><url-pattern>*.do</url-pattern></servlet-mapping></web-app>");
 write("WebRoot/WEB-INF/struts-config.xml","<struts-config><global-forwards><forward name='login' path='/index.jsp' redirect='true'/></global-forwards><action-mappings><action path='/auth' type='Login'><forward name='done' path='/area/items.do?command=list' redirect='true'/></action><action path='/area/items' type='Items' parameter='command'><forward name='list' path='/WEB-INF/list.jsp'/><forward name='edit' path='/WEB-INF/edit.jsp'/></action></action-mappings></struts-config>");
 write("src/Login.java","class Login extends Action{public ActionForward execute(ActionMapping m,ActionForm f,HttpServletRequest r,HttpServletResponse s){return m.findForward(\"done\");}}");
 write("src/Base.java","class Base extends DispatchAction{public ActionForward execute(ActionMapping m,ActionForm f,HttpServletRequest r,HttpServletResponse s){if(unknown)return m.findForward(\"login\");return super.execute(m,f,r,s);}}");
 write("src/Items.java","class Items extends Base{public ActionForward list(ActionMapping m,ActionForm f,HttpServletRequest r,HttpServletResponse s){return m.findForward(\"list\");}public ActionForward edit(ActionMapping m,ActionForm f,HttpServletRequest r,HttpServletResponse s){return m.findForward(\"edit\");}}");
 write("WebRoot/index.jsp","<form action='auth.do' method='post'><input type='submit'></form>");write("WebRoot/WEB-INF/list.jsp","List");write("WebRoot/WEB-INF/edit.jsp","Edit");
 var graph=new StrutsProjectAnalyzer().analyze(new ProjectScanner().scan(root));var nodes=new java.util.HashMap<String,io.screentrace.core.ApplicationGraph.GraphNode>();graph.nodes().forEach(n->nodes.put(n.id(),n));var start=graph.nodes().stream().filter(n->n.type()==NodeType.HANDLER&&"/auth".equals(n.attributes().get("path"))).findFirst().orElseThrow();var todo=new java.util.ArrayList<String>();todo.add(start.id());var seen=new java.util.HashSet<String>();var views=new java.util.TreeSet<String>();while(!todo.isEmpty()){var id=todo.remove(0);if(!seen.add(id))continue;var n=nodes.get(id);if(n.type()==NodeType.SCREEN){views.add(n.attributes().get("view"));continue;}graph.relationships().stream().filter(e->e.from().equals(id)&&java.util.Set.of(EdgeType.CALLS,EdgeType.FORWARDS_TO,EdgeType.HANDLED_BY,EdgeType.RENDERS).contains(e.type())).forEach(e->todo.add(e.to()));}
 assertEquals(java.util.Set.of("WebRoot/index.jsp","WebRoot/WEB-INF/list.jsp"),views);var login=graph.nodes().stream().filter(n->n.type()==NodeType.SCREEN&&"WebRoot/index.jsp".equals(n.attributes().get("view"))).findFirst().orElseThrow();assertEquals(java.util.List.of("/"),io.screentrace.parser.jsp.UrlGraphContribution.requestDirectories(graph,java.util.Set.of(login.id())));
 }
}
